                    "sql": "CREATE TABLE IF NOT EXISTS public.shipment_status_mapping ( SHIPPING_STATUS VARCHAR(256), Mapped_Status VARCHAR(256) ); DELETE FROM public.shipment_status_mapping; INSERT INTO public.shipment_status_mapping VALUES (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'), (\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'CONFIRMED\',\'Open\'), (\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'), (\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'), (\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'), (\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'), (\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'), (\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'), (\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'), (\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'), (\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'), (\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'), (\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'), (\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'), (\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'), (\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'), (\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'), (\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'), (\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'), (\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'), (\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'), (\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'), (\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); CREATE TABLE IF NOT EXISTS public.facility_pincode ( facility VARCHAR(256), pincode VARCHAR(20) ); drop table if exists public.quickshift_sales_consolidated_intermediate; CREATE TABLE public.quickshift_sales_consolidated_intermediate AS select * from public.unicommerce_sales_fact_items union ALL select * from public.easyecom_sales_fact_items union ALL select * from public.quickshift_b2b_sales_consolidated ; drop table if exists public.quickshift_sales_consolidated; CREATE TABLE public.quickshift_sales_consolidated AS select s.*, wm.\"Mapped Warehouse Name\", UPPER(mm.\"Order Type\") AS \"Order Type\", mm.\"Mapped Marketplace Name\", wm.\"Client Name\", ws.mapped_warehouse_status, SUBSTRING( data_source, POSITION(\' \' IN data_source) + 1 ) AS \"CLIENT\", data_source AS \"data_source_2\", CASE WHEN UPPER(mm.\"order type\") = \'D2C\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.inventory_assigned_date, s.order_date)) < 13 THEN DATE_TRUNC(\'DAY\',COALESCE(s.inventory_assigned_date,s.order_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD( DAY, 1, DATE_TRUNC( \'DAY\',COALESCE( s.inventory_assigned_date, s.order_date) )) + INTERVAL \'13 HOURS\' END WHEN UPPER(mm.\"order type\") = \'B2B\' THEN DATEADD(day, 2, COALESCE(s.inventory_assigned_date, s.order_date)) WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN COALESCE(s.inventory_assigned_date, s.order_date) END AS Expected_Completed_Date, CAST(CASE WHEN UPPER(mm.\"order type\") = \'D2C\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.fulfillment_tat, s.order_date)) < 13 THEN DATE_TRUNC(\'DAY\',COALESCE(s.fulfillment_tat,s.order_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD( DAY, 1, DATE_TRUNC( \'DAY\',COALESCE( s.fulfillment_tat, s.order_date) )) + INTERVAL \'13 HOURS\' END WHEN UPPER(mm.\"order type\") = \'B2B\' THEN DATEADD(day, 2, COALESCE(s.inventory_assigned_date, s.order_date)) WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN COALESCE(s.fulfillment_tat, s.order_date) END AS DATE)AS Acheived_Date, CASE WHEN cast(dispatch_date as date) <= CAST((CASE WHEN UPPER(mm.\"order type\") = \'D2C\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.fulfillment_tat, s.order_date)) < 13 THEN DATE_TRUNC(\'DAY\', COALESCE(s.fulfillment_tat, s.order_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD(DAY,1,DATE_TRUNC(\'DAY\', COALESCE(s.fulfillment_tat, s.order_date))) + INTERVAL \'13 HOURS\' END WHEN UPPER(mm.\"order type\") = \'B2B\' THEN DATEADD(day, 2, COALESCE(s.inventory_assigned_date, s.order_date)) WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN COALESCE(s.fulfillment_tat, s.order_date) END) AS DATE) THEN \'IN_TAT\' ELSE \'OUT_TAT\' END AS tat_status, CAST( CASE WHEN UPPER(mm.\"Order Type\") = \'B2B\' THEN aov.B2B WHEN UPPER(mm.\"Order Type\") = \'D2C\' THEN aov.D2C WHEN UPPER(mm.\"Order Type\") = \'MARKETPLACE\' THEN aov.MARKETPLACE END AS DOUBLE PRECISION) AS Revenue, CAST( CASE WHEN UPPER(mm.\"Order Type\") = \'B2B\' THEN aov.B2B WHEN UPPER(mm.\"Order Type\") = \'D2C\' THEN aov.D2C WHEN UPPER(mm.\"Order Type\") = \'MARKETPLACE\' THEN aov.MARKETPLACE END AS DOUBLE PRECISION )/NULLIF(COUNT(*) OVER (PARTITION BY reference_code), 0) AS AOV, CASE WHEN UPPER(oms_order_status) IN (\'COMPLETE\', \'SHIPPED\', \'READY TO DISPATCH\') THEN \'COMPLETED\' WHEN UPPER(oms_order_status) IN (\'ASSIGNED\', \'CREATED\') THEN \'PENDING\' ELSE \'OTHER\' END AS OMS_Status from public.quickshift_sales_consolidated_intermediate s left join (select * from (select *, row_number() over (partition by \"facility name\" order by \"facility name\") rw from public.gs_warehouse_mapping ) where rw = 1) wm on lower(wm.\"facility name\") = lower(s.warehouse) left join (select * from (select *, row_number() over (partition by \"Marketplace Name\" order by \"Marketplace Name\") rw from public.gs_marketplace_mapping ) where rw = 1) mm on lower(mm.\"Marketplace Name\") = lower(s.marketplace) left join (select * from (select \"order status\" as order_status, \"shipping status\" as shipping_status, \"warehouse status\" as mapped_warehouse_status, row_number() over (partition by \"shipping status\",\"order status\" order by 1,2) rw from public.gs_warehouse_status ) where rw = 1) ws on lower(ws.order_status) = lower(s.order_status) and lower(ws.shipping_status) = lower(s.shipping_status) LEFT JOIN ( SELECT * FROM( SELECT \"client name\" AS Client_Name, \"f b2b\" AS B2B, \"f b2c\" AS D2C, \"f b2c\" AS MARKETPLACE, ROW_NUMBER() OVER(PARTITION BY \"client name\") rw FROM public.QuickShift_Revenue_gs_Client_Wise_AOV ) where rw=1) aov ON LOWER(aov.Client_Name) = LOWER(wm.\"Client Name\") ; DROP TABLE IF EXISTS public.GS_State_ISO; CREATE TABLE public.GS_State_ISO ( state VARCHAR(256), iso_code VARCHAR(10) ); UPDATE public.quickshift_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\', \'ANDHRAPRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\', \'ASSAM HINDUISM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\', \'CHATTISGARH\', \'CHHATISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\', \'GUJRAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\', \'HIMANCHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\', \'KARANATAKA\', \'KARNATKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\', \'MADHYAPRADESH\', \'M. P\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\', \'MAHARASTRA\', \'MAHARASHATRA\', \'MAHASHTRA\', \'MUMBAI THANA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\', \'MEGALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\', \'ORISSA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\', \'TAMILNADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\', \'UTTER PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\', \'UTTRAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\', \'WEST BANGAL\', \'WB(KOLKATA & HOWRAH AREA)\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI\', \'DD\', \'DAMAN AND DIU\', \'DAMAN & DIU\', \'DADRA & NAGAR HAVELI AND DAMAN & DIU\', \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\', \'DADRA AND NAGAR HAV.\') THEN \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\', \'NEW DELHI\', \'NCR\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\', \'PONDICHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' WHEN UPPER(state) IN (\'AUCKLAND\', \'UNITED KINGDOM (+44)\', \'NON-US\', \'ZEELAND\', \'SINGAPORE\', \'BARCELONA\') THEN NULL WHEN UPPER(state) IN (\'INDIA\', \'1493\', \'BJP.TEAM211@GMAIL.COM\') THEN NULL WHEN UPPER(state) IN (\'NOT SPECIFIED\', \'\') THEN NULL ELSE state END; drop table if exists public.quickshift_sales_consolidated_table_2; CREATE TABLE public.quickshift_sales_consolidated_table_2 AS select s.*, wm.\"Mapped Warehouse Name\", UPPER(mm.\"Order Type\") AS \"Order Type\", mm.\"Mapped Marketplace Name\", wm.\"Client Name\", ws.mapped_warehouse_status, CASE WHEN UPPER(mm.\"order type\") = \'D2C\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.inventory_assigned_date, s.order_date)) < 13 THEN DATE_TRUNC(\'DAY\',COALESCE(s.inventory_assigned_date,s.order_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD( DAY, 1, DATE_TRUNC( \'DAY\',COALESCE( s.inventory_assigned_date, s.order_date) )) + INTERVAL \'13 HOURS\' END WHEN UPPER(mm.\"order type\") = \'B2B\' THEN DATEADD(day, 2, COALESCE(s.inventory_assigned_date, s.order_date)) WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN COALESCE(s.inventory_assigned_date, s.order_date) END AS Expected_Completed_Date, CASE WHEN UPPER(oms_order_status) IN (\'COMPLETE\', \'SHIPPED\', \'READY TO DISPATCH\') THEN \'COMPLETED\' WHEN UPPER(oms_order_status) IN (\'ASSIGNED\', \'CREATED\') THEN \'PENDING\' ELSE \'OTHER\' END AS OMS_Status from public.quickshift_sales_consolidated_intermediate s left join (select * from (select *, row_number() over (partition by \"facility name\" order by \"facility name\") rw from public.gs_warehouse_mapping ) where rw = 1) wm on lower(wm.\"facility name\") = lower(s.warehouse) left join (select * from (select *, row_number() over (partition by \"Marketplace Name\" order by \"Marketplace Name\") rw from public.gs_marketplace_mapping ) where rw = 1) mm on lower(mm.\"Marketplace Name\") = lower(s.marketplace) left join (select * from (select \"order status\" as order_status, \"shipping status\" as shipping_status, \"warehouse status\" as mapped_warehouse_status, row_number() over (partition by \"shipping status\",\"order status\" order by 1,2) rw from public.gs_warehouse_status ) where rw = 1) ws on lower(ws.order_status) = lower(s.order_status) and lower(ws.shipping_status) = lower(s.shipping_status) ; drop table if exists public.quickshift_sales_consolidated_Invoice_date; CREATE TABLE public.quickshift_sales_consolidated_Invoice_date AS select s.*, wm.\"Mapped Warehouse Name\", UPPER(mm.\"Order Type\") AS \"Order Type\", mm.\"Mapped Marketplace Name\", wm.\"Client Name\", ws.mapped_warehouse_status, CASE WHEN UPPER(mm.\"order type\") = \'D2C\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.inventory_assigned_date, s.order_date)) < 13 THEN DATE_TRUNC(\'DAY\',COALESCE(s.inventory_assigned_date,s.order_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD( DAY, 1, DATE_TRUNC( \'DAY\',COALESCE( s.inventory_assigned_date, s.order_date) )) + INTERVAL \'13 HOURS\' END WHEN UPPER(mm.\"order type\") = \'B2B\' THEN DATEADD(day, 2, COALESCE(s.inventory_assigned_date, s.order_date)) WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN COALESCE(s.inventory_assigned_date, s.order_date) END AS Expected_Completed_Date, CAST( CASE WHEN UPPER(mm.\"Order Type\") = \'B2B\' THEN aov.B2B WHEN UPPER(mm.\"Order Type\") = \'D2C\' THEN aov.D2C WHEN UPPER(mm.\"Order Type\") = \'MARKETPLACE\' THEN aov.MARKETPLACE END AS DOUBLE PRECISION) AS Revenue, CAST( CASE WHEN UPPER(mm.\"Order Type\") = \'B2B\' THEN aov.B2B WHEN UPPER(mm.\"Order Type\") = \'D2C\' THEN aov.D2C WHEN UPPER(mm.\"Order Type\") = \'MARKETPLACE\' THEN aov.MARKETPLACE END AS DOUBLE PRECISION )/NULLIF(COUNT(*) OVER (PARTITION BY reference_code), 0) AS AOV, CASE WHEN UPPER(oms_order_status) IN (\'COMPLETE\', \'SHIPPED\', \'READY TO DISPATCH\') THEN \'COMPLETED\' WHEN UPPER(oms_order_status) IN (\'ASSIGNED\', \'CREATED\') THEN \'PENDING\' ELSE \'OTHER\' END AS OMS_Status from public.quickshift_sales_consolidated_intermediate s left join (select * from (select *, row_number() over (partition by \"facility name\" order by \"facility name\") rw from public.gs_warehouse_mapping ) where rw = 1) wm on lower(wm.\"facility name\") = lower(s.warehouse) left join (select * from (select *, row_number() over (partition by \"Marketplace Name\" order by \"Marketplace Name\") rw from public.gs_marketplace_mapping ) where rw = 1) mm on lower(mm.\"Marketplace Name\") = lower(s.marketplace) left join (select * from (select \"order status\" as order_status, \"shipping status\" as shipping_status, \"warehouse status\" as mapped_warehouse_status, row_number() over (partition by \"shipping status\",\"order status\" order by 1,2) rw from public.gs_warehouse_status ) where rw = 1) ws on lower(ws.order_status) = lower(s.order_status) and lower(ws.shipping_status) = lower(s.shipping_status) LEFT JOIN ( SELECT * FROM( SELECT \"client name\" AS Client_Name, \"f b2b\" AS B2B, \"f b2c\" AS D2C, \"f b2c\" AS MARKETPLACE, ROW_NUMBER() OVER(PARTITION BY \"client name\") rw FROM public.QuickShift_Revenue_gs_Client_Wise_AOV ) where rw=1) aov ON LOWER(aov.Client_Name) = LOWER(wm.\"Client Name\") ; drop table if exists public.quickshift_sales_consolidated_intermediate_EE_UNI_Date; CREATE TABLE public.quickshift_sales_consolidated_intermediate_EE_UNI_Date AS select marketplace, order_id, reference_code, shipping_last_update_date, sku, sku_code, product_id, order_status, order_date, quantity, oms_order_status, shipping_status, final_shipping_status, saleorderitemcode, sales_order_item_id, awb, courier, dispatch_date, delivered_date, warehouse, invoice_date, inventory_assigned_date AS EE_UNI_Date, data_source from public.easyecom_sales_fact_items UNION ALL select marketplace, order_id, reference_code, shipping_last_update_date, marketplace_sku, sku_code, product_id, order_status, order_date, quantity, oms_order_status, shipping_status, final_shipping_status, saleorderitemcode, sales_order_item_id, awb, courier, dispatch_date, delivered_date, warehouse, invoice_date, shipping_package_creation_date AS EE_UNI_Date, data_source from public.unicommerce_sales_fact_items; drop table if exists public.quickshift_sales_consolidated_EE_UNI_Date; CREATE TABLE public.quickshift_sales_consolidated_EE_UNI_Date AS select s.*, wm.\"Mapped Warehouse Name\", UPPER(mm.\"Order Type\") AS \"Order Type\", mm.\"Mapped Marketplace Name\", wm.\"Client Name\", ws.mapped_warehouse_status from public.quickshift_sales_consolidated_intermediate_EE_UNI_Date s left join (select * from (select *, row_number() over (partition by \"facility name\" order by \"facility name\") rw from public.gs_warehouse_mapping ) where rw = 1) wm on lower(wm.\"facility name\") = lower(s.warehouse) left join (select * from (select *, row_number() over (partition by \"Marketplace Name\" order by \"Marketplace Name\") rw from public.gs_marketplace_mapping ) where rw = 1) mm on lower(mm.\"Marketplace Name\") = lower(s.marketplace) left join (select * from (select \"order status\" as order_status, \"shipping status\" as shipping_status, \"warehouse status\" as mapped_warehouse_status, row_number() over (partition by \"shipping status\",\"order status\" order by 1,2) rw from public.gs_warehouse_status ) where rw = 1) ws on lower(ws.order_status) = lower(s.order_status) and lower(ws.shipping_status) = lower(s.shipping_status) ; drop table if exists public.quickshift_sales_consolidated_Harshal_date; CREATE TABLE public.quickshift_sales_consolidated_Harshal_date AS select s.*, wm.\"Mapped Warehouse Name\", UPPER(mm.\"Order Type\") AS \"Order Type\", mm.\"Mapped Marketplace Name\", wm.\"Client Name\", ws.mapped_warehouse_status, CASE WHEN UPPER(s.shipping_provider) LIKE \'%QUICKSHIFT%\' THEN \'QS SHIPPING\' WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN \'MARKETPLACE\' WHEN UPPER(mm.\"order type\") = \'D2C\' AND UPPER(wm.\"Client Name\") = \'GHAR SOAPS\' THEN \'GHAR SOAPS\' ELSE \'CLIENT SHIPPING\' END AS Harshal_Shipping, CASE WHEN UPPER(mm.\"order type\") = \'D2C\' AND UPPER(wm.\"Client Name\") = \'GHAR SOAPS\' THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.inventory_assigned_date, s.order_date)) < 13 THEN DATE_TRUNC(\'DAY\',COALESCE(s.inventory_assigned_date,s.order_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD( DAY, 1, DATE_TRUNC( \'DAY\',COALESCE( s.inventory_assigned_date, s.order_date) )) + INTERVAL \'13 HOURS\' END WHEN UPPER(mm.\"order type\") = \'MARKETPLACE\' THEN COALESCE(s.fulfillment_tat, s.order_date) WHEN UPPER(mm.\"order type\") = \'B2B\' THEN DATEADD(day, 2, COALESCE(s.inventory_assigned_date, s.order_date)) WHEN UPPER(s.shipping_provider) LIKE \'%QUICKSHIFT%\' OR (s.shipping_provider IS NOT NULL AND (s.awb IS NULL OR TRIM(s.awb) = \'\') AND UPPER(wm.\"Client Name\") NOT IN (\'SUPER YOU\',\'FAST AND UP\',\'BENNYS BOWL\',\'BENNYS BOWS\')) THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.order_date, s.inventory_assigned_date)) < 13 THEN DATE_TRUNC(\'DAY\', COALESCE(s.order_date, s.inventory_assigned_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD(DAY, 1, DATE_TRUNC(\'DAY\', COALESCE(s.order_date, s.inventory_assigned_date))) + INTERVAL \'13 HOURS\' END WHEN UPPER(s.shipping_provider) NOT LIKE \'%QUICKSHIFT%\' OR ( s.shipping_provider IS NOT NULL AND (s.awb IS NULL OR TRIM(s.awb) = \'\') AND UPPER(wm.\"Client Name\") IN (\'SUPER YOU\',\'FAST AND UP\',\'BENNYS BOWL\',\'BENNYS BOWS\') ) THEN CASE WHEN EXTRACT(HOUR FROM COALESCE(s.order_date, s.inventory_assigned_date)) < 13 THEN DATE_TRUNC(\'DAY\', COALESCE(s.order_date, s.inventory_assigned_date)) + INTERVAL \'13 HOURS\' ELSE DATEADD(DAY, 1, DATE_TRUNC(\'DAY\', COALESCE(s.order_date, s.inventory_assigned_date))) + INTERVAL \'13 HOURS\' END END AS Harshal_Date from public.quickshift_sales_consolidated_intermediate s left join (select * from (select *, row_number() over (partition by \"facility name\" order by \"facility name\") rw from public.gs_warehouse_mapping ) where rw = 1) wm on lower(wm.\"facility name\") = lower(s.warehouse) left join (select * from (select *, row_number() over (partition by \"Marketplace Name\" order by \"Marketplace Name\") rw from public.gs_marketplace_mapping ) where rw = 1) mm on lower(mm.\"Marketplace Name\") = lower(s.marketplace) left join (select * from (select \"order status\" as order_status, \"shipping status\" as shipping_status, \"warehouse status\" as mapped_warehouse_status, row_number() over (partition by \"shipping status\",\"order status\" order by 1,2) rw from public.gs_warehouse_status ) where rw = 1) ws on lower(ws.order_status) = lower(s.order_status) and lower(ws.shipping_status) = lower(s.shipping_status) ;",
                    "transaction": true
